<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($pageTitle) ?></title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/catalog.css"><link rel="stylesheet" href="/assets/css/storefront-phase3.css"></head>
<body><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><div class="search-wrap"><form class="search" method="get" action="/shop" autocomplete="off"><label class="sr-only" for="shop-search">Search</label><input id="shop-search" name="q" placeholder="Search the collection" value="<?= htmlspecialchars($search) ?>" data-search-input><button aria-label="Search">⌕</button></form><div class="search-suggest" data-search-suggest hidden></div></div><nav class="header-actions"><a class="sell-with-us" href="/vendor/register">Sell with us</a><a href="/account">Account</a><a href="/">Home</a></nav></header>
<main class="catalog-shell"><div class="catalog-heading"><div><p class="eyebrow">The collection</p><h1>Find something<br><i>worth keeping.</i></h1></div><p><?= htmlspecialchars((string) ($productCount ?? count($products))) ?> pieces, thoughtfully gathered.</p></div>
<form class="catalog-filters" method="get" action="/shop"><input type="hidden" name="q" value="<?= htmlspecialchars($search) ?>"><label>Category<select name="category"><option value="">All categories</option><?php foreach ($categories as $item): ?><option value="<?= htmlspecialchars($item['slug']) ?>" <?= $category === $item['slug'] ? 'selected' : '' ?>><?= htmlspecialchars($item['name']) ?></option><?php endforeach; ?></select></label><label>Region<select name="region"><option value="">All regions</option><?php foreach (($filterOptions['regions'] ?? []) as $item): ?><option value="<?= htmlspecialchars($item['value']) ?>" <?= ($region ?? '') === $item['value'] ? 'selected' : '' ?>><?= htmlspecialchars($item['value']) ?></option><?php endforeach; ?></select></label><label>Craft<select name="craft"><option value="">All craft</option><?php foreach (($filterOptions['crafts'] ?? []) as $item): ?><option value="<?= htmlspecialchars($item['value']) ?>" <?= ($craft ?? '') === $item['value'] ? 'selected' : '' ?>><?= htmlspecialchars($item['value']) ?></option><?php endforeach; ?></select></label><label>Sort<select name="sort"><option value="">Newest</option><option value="price_asc" <?= ($sort ?? '') === 'price_asc' ? 'selected' : '' ?>>Price: low to high</option><option value="price_desc" <?= ($sort ?? '') === 'price_desc' ? 'selected' : '' ?>>Price: high to low</option></select></label><button class="button" type="submit">Refine <span>→</span></button></form>
<div class="catalog-layout"><aside><h2>Browse by</h2><a class="<?= $category === '' ? 'active' : '' ?>" href="/shop">All pieces</a><?php foreach ($categories as $item): ?><a class="<?= $category === $item['slug'] ? 'active' : '' ?>" href="/shop?category=<?= urlencode($item['slug']) ?>"><?= htmlspecialchars($item['name']) ?></a><?php endforeach; ?></aside><section><div class="catalog-toolbar"><span><?= $search !== '' ? 'Results for “' . htmlspecialchars($search) . '”' : 'Latest arrivals' ?></span><span><?= count($products) ?> shown</span></div><div class="catalog-grid"><?php foreach ($products as $product): ?><article class="catalog-card"><a href="/product/<?= urlencode($product['slug']) ?>"><div class="catalog-image"><img loading="lazy" src="<?= htmlspecialchars($product['image']) ?>" alt="<?= htmlspecialchars($product['name']) ?>"></div><p><?= htmlspecialchars($product['category']) ?></p><h2><?= htmlspecialchars($product['name']) ?></h2><strong><?= htmlspecialchars($product['price']) ?></strong></a><small>By <a href="/vendor/<?= urlencode($product['vendor_slug']) ?>"><?= htmlspecialchars($product['vendor']) ?></a></small></article><?php endforeach; ?></div><?php if (!$products): ?><p class="empty-state">No pieces match those filters yet.</p><?php endif; ?><?php $pageCount = max(1, (int) ceil(($productCount ?? count($products)) / 12)); if ($pageCount > 1): ?><nav class="pagination" aria-label="Collection pages"><?php for ($pageNumber = 1; $pageNumber <= $pageCount; $pageNumber++): ?><a class="<?= $pageNumber === ($page ?? 1) ? 'active' : '' ?>" href="<?= htmlspecialchars('/shop?' . http_build_query(array_filter(['q' => $search, 'category' => $category, 'region' => $region, 'craft' => $craft, 'sort' => $sort, 'page' => $pageNumber]))) ?>"><?= $pageNumber ?></a><?php endfor; ?></nav><?php endif; ?></section></div></main><script src="/assets/js/search-suggest.js"></script></body></html>
